INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2754367, 383965, 60120, '<td valign="top">rope too new for the boat...</td>', 'rope too new for the boat...', '2006-08-23 21:03:35.000000', NULL, 1),
(2754372, 384139, 60120, '<td valign="top">OK! I missed it...nice photo</td>', 'OK! I missed it...nice photo', '2006-08-23 21:04:31.000000', NULL, 1),
(2754378, 384165, 60120, '<td valign="top">love the title...Frayed knot!!!</td>', 'love the title...Frayed knot!!!', '2006-08-23 21:05:43.000000', NULL, 1),
(2754379, 383562, 61818, '<td valign="top">Reasons this is a poor entry:<br/> <br/>1 - Size.  The image itself is probably 1/4th the size allowed for an entry.  You''ve got space to work with, put it to use.<br/> <br/>2 - The lighting.  A very harsh light, probably a flash, the has completely flattened what might have been some interesting detail work on the headboard.  This isn''t a ''headboard'' challenge, so you''d have been doomed regardless but still it would have been more appealing to the eye.<br/> <br/>3 - Content.  This is a challenge for shooting ''Rope'' with a very specific description of what ''rope'' is.  If that is a rope, I can''t tell and it is so insignificant in the overall photo that it may as well not even be present.  Honestly, it looks like a piece of shoe string tied around the post.<br/> <br/>4 - Composition.  What little you have presented to the eye here is presented poorly.  The shot is tilted to the right and there is a void to the left of the post that serves no purpose.  It would have been better to get the post all the way to the left of the photo and more or less completely fill the frame with the bed.<br/> <br/>People ask for comments when they get low scores.  I am sure you are going to score very, very low so I hope these comments help.  At the same time, when I see photos like this in challenges I have to wonder if it is a joke or if the submitter cares at all about their work so it makes me wonder if it is just time wasted leaving a comment at all.</td>', 'Reasons this is a poor entry: 1 - Size.  The image itself is probably 1/4th the size allowed for an entry.  You''ve got space to work with, put it to use. 2 - The lighting.  A very harsh light, probably a flash, the has completely flattened what might have been some interesting detail work on the headboard.  This isn''t a ''headboard'' challenge, so you''d have been doomed regardless but still it would have been more appealing to the eye. 3 - Content.  This is a challenge for shooting ''Rope'' with a very specific description of what ''rope'' is.  If that is a rope, I can''t tell and it is so insignificant in the overall photo that it may as well not even be present.  Honestly, it looks like a piece of shoe string tied around the post. 4 - Composition.  What little you have presented to the eye here is presented poorly.  The shot is tilted to the right and there is a void to the left of the post that serves no purpose.  It would have been better to get the post all the way to the left of the photo and more or less completely fill the frame with the bed. People ask for comments when they get low scores.  I am sure you are going to score very, very low so I hope these comments help.  At the same time, when I see photos like this in challenges I have to wonder if it is a joke or if the submitter cares at all about their work so it makes me wonder if it is just time wasted leaving a comment at all.', '2006-08-23 21:05:52.000000', NULL, 1),
(2754382, 383925, 60120, '<td valign="top">Political yet not grasping...</td>', 'Political yet not grasping...', '2006-08-23 21:06:26.000000', NULL, 1),
