(2770083, 384020, 45004, '<td valign="top">Nice Image. I like the shallow DOF and the hard lighting.</td>', 'Nice Image. I like the shallow DOF and the hard lighting.', '2006-08-29 10:34:50.000000', NULL, 1),
(2770090, 383505, 5792, '<td valign="top">Unique interpretation that strongly fits the challenge topic exceptionally well. Surprising that no one else thought of it. Given the theme, red tones work well here and the arrangement, particularly of the candles illuminating "Professor Plum" is fine.<br/> Candlelight refections are a bit of a distraction. Perhaps curling the noose around more toward the middle of the frame could cover that up, or angling the shot slightly from the left closer for highlighting the rope more is worth consideration. There is a lot of empty space in the lower right foreground. Curling the top part of the noose around on that side rather than having it directly under the noose could fill that spot. A little more sharpness to bring out the fine detail would be nice. The table lighting is unbalanced where the right side is better illuminated than the left.<br/> Overall this is a nice shot.</td>', 'Unique interpretation that strongly fits the challenge topic exceptionally well. Surprising that no one else thought of it. Given the theme, red tones work well here and the arrangement, particularly of the candles illuminating "Professor Plum" is fine. Candlelight refections are a bit of a distraction. Perhaps curling the noose around more toward the middle of the frame could cover that up, or angling the shot slightly from the left closer for highlighting the rope more is worth consideration. There is a lot of empty space in the lower right foreground. Curling the top part of the noose around on that side rather than having it directly under the noose could fill that spot. A little more sharpness to bring out the fine detail would be nice. The table lighting is unbalanced where the right side is better illuminated than the left. Overall this is a nice shot.', '2006-08-29 10:37:01.000000', NULL, 1),
(2770091, 383438, 45004, '<td valign="top">I like the way the rope is tight together and the sheen off opf the rope.</td>', 'I like the way the rope is tight together and the sheen off opf the rope.', '2006-08-29 10:37:08.000000', NULL, 1),
(2770104, 382362, 42875, '<td valign="top">My favorite of all the submissions!  This was one of the few that was inventive and original!</td>', 'My favorite of all the submissions!  This was one of the few that was inventive and original!', '2006-08-29 10:42:19.000000', NULL, 1),
