(2771112, 384058, 64122, '<td valign="top">What are the specs on the hand?</td>', 'What are the specs on the hand?', '2006-08-29 18:08:56.000000', NULL, 1),
(2771116, 383624, 35602, '<td valign="top">Like the idea.  The blue is lovely in the background and serves as a great backdrop for the spars.  Found the lines and spars to be too busy, though.  Maybe a little less of them would have had more impact.</td>', 'Like the idea.  The blue is lovely in the background and serves as a great backdrop for the spars.  Found the lines and spars to be too busy, though.  Maybe a little less of them would have had more impact.', '2006-08-29 18:12:40.000000', NULL, 1),
(2771125, 383426, 35602, '<td valign="top">Blue background really enhances the rope.  However, the rope is way overexposed. Very little detail.  Maybe an exposure compensation to make the detail come out better would have avoided the overexposure.</td>', 'Blue background really enhances the rope.  However, the rope is way overexposed. Very little detail.  Maybe an exposure compensation to make the detail come out better would have avoided the overexposure.', '2006-08-29 18:21:10.000000', NULL, 1),
(2771127, 383311, 35602, '<td valign="top">Very nice abstract.  Black and white really works with it as well.</td>', 'Very nice abstract.  Black and white really works with it as well.', '2006-08-29 18:22:17.000000', NULL, 1),
(2771129, 383978, 35602, '<td valign="top">This was a well done still life.  Love the grain on it and the tone.</td>', 'This was a well done still life.  Love the grain on it and the tone.', '2006-08-29 18:24:23.000000', NULL, 1),
